import React, { useEffect, useState, useCallback, useMemo } from "react";
import { v4 as uuidv4 } from 'uuid';
import { Question, Message, DomainStatus, AnswerAttempt } from './types';
import Header from './components/Header';
import ChatPanel from './components/ChatPanel';
import Sidebar from './components/Sidebar';

const App: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [questions, setQuestions] = useState<Question[]>([]);
  const [domainStatuses, setDomainStatuses] = useState<DomainStatus[]>([]);
  const [overallScore, setOverallScore] = useState<number>(0);
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [editingMessageId, setEditingMessageId] = useState<string | null>(null);

  // BASİTLEŞTİRİLMİŞ "Timeline Walker"
  // Artık activeAttemptIndex'i dikkate almaz, her zaman ilk ve tek versiyonu takip eder.
  const getVisibleMessages = useCallback((allMessages: Message[]): Message[] => {
    if (allMessages.length === 0) return [];
    
    // Her zaman ilk mesajla başla (genellikle ilk sorudur)
    const visible: Message[] = [allMessages[0]];

    while (true) {
      const lastVisible = visible[visible.length - 1];

      if (lastVisible.type === 'question') {
        // Bu soruya verilmiş bir cevap ara.
        const response = allMessages.find(m => 
          m.type === 'user_response' && 
          m.answeredQuestionId === lastVisible.question?.id &&
          m.attempts && m.attempts.length > 0 // Cevabın bir içeriği olduğundan emin ol
        );
        
        if (response) {
          visible.push(response);
        } else {
          break; // Cevap yoksa akış burada biter.
        }
      } else if (lastVisible.type === 'user_response') {
        // Her zaman ilk ve tek attempt'e göre bir sonraki soruyu bul.
        const firstAttempt = lastVisible.attempts?.[0];
        
        if (!firstAttempt || firstAttempt.next_question_id === null) {
          break; // Değerlendirme bitti veya bu dalın sonu.
        }

        // Bir sonraki soruyu bul.
        const nextQuestion = allMessages.find(m => 
          m.type === 'question' && 
          m.question?.id === firstAttempt.next_question_id
        );
        
        if (nextQuestion) {
          visible.push(nextQuestion);
        } else {
          break;
        }
      } else {
        break; // Hata mesajı vb. ise akışı bitir.
      }
    }
    return visible;
  }, []);

  const visibleMessages = useMemo(() => getVisibleMessages(messages), [messages, getVisibleMessages]);
  
  const currentQuestionId = useMemo(() => {
    const lastVisible = visibleMessages[visibleMessages.length - 1];
    return lastVisible?.type === 'question' ? lastVisible.question?.id ?? null : null;
  }, [visibleMessages]);

  useEffect(() => {
    fetch("http://localhost:3001/questions")
      .then(res => res.json())
      .then(data => {
        setQuestions(data);
        const firstQuestion = data[0];
        
        setMessages([{
          id: uuidv4(),
          sender: 'AI',
          type: 'question',
          question: firstQuestion,
          text: ""
        }]);

        const initialDomains: DomainStatus[] = [...new Set(data.map(q => q.domain_name))]
          .map(name => ({
            name,
            status: name === firstQuestion.domain_name ? 'In Progress' : 'Pending',
            score: 0
          }));
        setDomainStatuses(initialDomains);
      })
      .catch(err => {
        console.error("Error fetching questions:", err);
        setMessages([{
          id: uuidv4(),
          sender: 'AI',
          type: 'error',
          text: "Backend'e bağlanılamadı."
        }]);
      })
      .finally(() => setIsLoading(false));
  }, []);

  const recalculateScores = useCallback((currentVisibleMessages: Message[], allQuestions: Question[]) => {
    // Bu fonksiyonun içindeki mantık, her zaman ilk attempt'i baz alacağı için zaten
    // versiyonsuz modelle uyumludur, değişiklik gerekmez.
    if (allQuestions.length === 0) return;

    const domainData: { [key: string]: { score: number; answeredQuestions: Set<number> } } = {};
    const domains = [...new Set(allQuestions.map(q => q.domain_name))];

    domains.forEach(name => {
      domainData[name] = { score: 0, answeredQuestions: new Set() };
    });

    for (const msg of currentVisibleMessages) {
      if (msg.type === 'user_response' && msg.answeredQuestionId && msg.attempts) {
        const question = allQuestions.find(q => q.id === msg.answeredQuestionId);
        if (question) {
          domainData[question.domain_name].answeredQuestions.add(question.id);
        }
      }
    }

    domains.forEach(name => {
      const totalQuestionsInDomain = allQuestions.filter(q => q.domain_name === name).length;
      const questionWeight = 100 / (totalQuestionsInDomain || 1);
      let domainScore = 0;

      currentVisibleMessages
        .filter(m => m.type === 'user_response' && m.answeredQuestionId && domainData[name].answeredQuestions.has(m.answeredQuestionId))
        .forEach(msg => {
          const firstAttempt = msg.attempts?.[0]; // Her zaman ilk ve tek attempt'i al
          if (firstAttempt) {
            domainScore += (firstAttempt.score / 100) * questionWeight;
          }
        });
      
      domainData[name].score = domainScore;
    });

    const lastQuestionMsg = [...currentVisibleMessages].reverse().find(m => m.type === 'question' && m.question);
    const currentDomainName = lastQuestionMsg?.question?.domain_name;

    const newDomainStatuses: DomainStatus[] = domains.map(name => {
      const data = domainData[name];
      const answeredCount = data.answeredQuestions.size;
      const totalCount = allQuestions.filter(q => q.domain_name === name).length;
      let status: 'Complete' | 'In Progress' | 'Pending' = 'Pending';

      if (answeredCount > 0) {
        status = (answeredCount >= totalCount || name !== currentDomainName) ? 'Complete' : 'In Progress';
      } else if (name === currentDomainName) {
        status = 'In Progress';
      }

      return { name, score: Math.min(100, data.score), status };
    });

    const totalScore = newDomainStatuses.reduce((acc, curr) => acc + curr.score, 0);
    setOverallScore(totalScore / (newDomainStatuses.length || 1));
    setDomainStatuses(newDomainStatuses);
  }, []);

  useEffect(() => {
    recalculateScores(visibleMessages, questions);
  }, [visibleMessages, questions, recalculateScores]);

  const handleSendMessage = async (prompt: string) => {
    if (!currentQuestionId || isLoading) return;
    setIsLoading(true);

    const userMessage: Message = {
      id: uuidv4(),
      sender: 'User',
      type: 'user_response',
      answeredQuestionId: currentQuestionId,
      // Versiyonsuz modelde bu alanlar her zaman böyle başlar
      attempts: [], 
      activeAttemptIndex: 0,
      text: ""
    };
    
    // Optimistic update: Kullanıcının cevabını hemen ekle
    setMessages(prev => [...prev.filter(m => m.answeredQuestionId !== currentQuestionId), userMessage]);

    try {
      const res = await fetch("http://localhost:3001/ask", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ prompt, previous_question_id: currentQuestionId })
      });
      
      if (!res.ok) throw new Error(`API error: ${res.statusText}`);
      const apiResponse = await res.json();

      const newAttempt: AnswerAttempt = {
        text: prompt, score: apiResponse.score, ai_comment: apiResponse.comment,
        ai_task: apiResponse.task, db_answer_id: apiResponse.db_answer_id,
        next_question_id: apiResponse.next_question_id,
      };

      setMessages(currentMessages => {
        const updatedMessages = [...currentMessages];
        const messageToUpdate = updatedMessages.find(m => m.id === userMessage.id);
        if (messageToUpdate) {
          messageToUpdate.attempts = [newAttempt]; // Tek attempt'i ayarla
        }

        if (apiResponse.next_question_id !== null) {
          const nextQuestion = questions.find(q => q.id === apiResponse.next_question_id);
          if (nextQuestion) {
            updatedMessages.push({
              id: uuidv4(), sender: 'AI', type: 'question', question: nextQuestion, text: ""
            });
          }
        }
        return updatedMessages;
      });

    } catch (err) {
      console.error("Error sending message:", err);
      setMessages(prev => prev.filter(m => m.id !== userMessage.id)); // Hata durumunda optimistik mesajı kaldır
    } finally {
      setIsLoading(false);
    }
  };

  // YIKICI EDİTLEME: Bu fonksiyon eski cevabın üzerine yazar.
  const handleEditMessage = useCallback(async (messageId: string, newText: string) => {
    const message = messages.find(m => m.id === messageId);
    if (!message || !message.answeredQuestionId) return;

    setIsLoading(true);
    setEditingMessageId(null);

    // Düzenlemeden sonra gelen tüm mesajları silerek temiz bir başlangıç yap
    const messageIndex = messages.findIndex(m => m.id === messageId);
    const messagesUpToEdit = messages.slice(0, messageIndex + 1);

    try {
      const res = await fetch("http://localhost:3001/ask", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          prompt: newText,
          previous_question_id: message.answeredQuestionId
        }),
      });
      
      if (!res.ok) throw new Error(`API error: ${res.statusText}`);
      const apiResponse = await res.json();

      const newAttempt: AnswerAttempt = {
        text: newText, score: apiResponse.score, ai_comment: apiResponse.comment,
        ai_task: apiResponse.task, db_answer_id: apiResponse.db_answer_id,
        next_question_id: apiResponse.next_question_id,
      };

      setMessages(() => {
        const messageToUpdate = messagesUpToEdit.find(m => m.id === messageId);
        if (messageToUpdate) {
          messageToUpdate.attempts = [newAttempt]; // Tek attempt'i ayarla
        }

        if (apiResponse.next_question_id !== null) {
          const nextQuestion = questions.find(q => q.id === apiResponse.next_question_id);
          if (nextQuestion) {
            messagesUpToEdit.push({
              id: uuidv4(), sender: 'AI', type: 'question', question: nextQuestion, text: ""
            });
          }
        }
        return messagesUpToEdit;
      });

    } catch (err) {
      console.error("Error while editing message:", err);
    } finally {
      setIsLoading(false);
    }
  }, [messages, questions]);
  
  // BASİTLEŞTİRİLMİŞ GERİ GİTME: Son cevabı ve sorusunu siler.
  const handlePreviousQuestion = () => {
    const lastResponseIndex = messages.findLastIndex(m => m.type === 'user_response');
    if (lastResponseIndex === -1) return;

    setMessages(prev => prev.slice(0, lastResponseIndex));
  };

  return (
    <div className="bg-[#0f0f23] text-gray-200 font-sans h-screen flex flex-col">
      <Header />
      <div className="flex flex-1 overflow-hidden min-h-0">
        <ChatPanel
          messages={visibleMessages}
          onSendMessage={handleSendMessage}
          isLoading={isLoading}
          currentQuestionId={currentQuestionId}
          editingMessageId={editingMessageId}
          setEditingMessageId={setEditingMessageId}
          onEditMessage={handleEditMessage}
          // handleNavigateAttempt kaldırıldığı için prop da kaldırıldı.
          onNavigateAttempt={() => {}} 
        />
        <Sidebar statuses={domainStatuses} overallScore={overallScore} />
      </div>
    </div>
  );
};

export default App;
